voluteModule -->\n\nEditionConvoluteComponent->EditionConvoluteModule\n\n\n\n\n\nEditionConvoluteComponent \n\nEditionConvoluteComponent \n\nEditionConvoluteComponent  -->\n\nEditionConvoluteModule->EditionConvoluteComponent \n\n\n\n\n\nEditionFolioViewerFolioModule\n\nEditionFolioViewerFolioModule\n\nEditionConvoluteModule -->\n\nEditionFolioViewerFolioModule->EditionConvoluteModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nEditionConvoluteModule -->\n\nSharedModule->EditionConvoluteModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/views/edition-view/edition-outlets/edition-complex/edition-detail/edition-sheets/edition-convolute/edition-convolute.module.ts\n        \n\n\n\n        \n            Description\n        \n        \n            The EditionConvolute module.\nIt embeds the edition convolute components as well as the\nFolioModule and SharedModule.\n\n        \n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            EditionConvoluteComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            EditionFolioViewerFolioModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n                \n                    Exports\n                    \n                        \n                            EditionConvoluteComponent\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { SharedModule } from '@awg-shared/shared.module';\n\nimport { EditionConvoluteComponent } from './edition-convolute.component';\nimport { EditionFolioViewerFolioModule } from './edition-folio-viewer/edition-folio-viewer.module';\n\n/**\n * The EditionConvolute module.\n *\n * It embeds the edition convolute components as well as the\n * {@link FolioModule} and {@link SharedModule}.\n */\n@NgModule({\n    imports: [SharedModule, EditionFolioViewerFolioModule],\n    declarations: [EditionConvoluteComponent],\n    exports: [EditionConvoluteComponent],\n})\nexport class EditionConvoluteModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   \n    \n         results matching \"\"\n        \n    \n    \n        No results matching \"\"\n    \n\n"},"components/EditionDetailComponent.html":{"url":"components/EditionDetailComponent.html","title":"component - EditionDetailComponent","body":"\n                   \n\n\n\n\n\n  Components\n  \n  EditionDetailComponent\n\n\n\n        \n            Info\n        \n        \n            Source\n        \n        \n            Template\n        \n        \n            Styles\n        \n        \n            DOM Tree\n        \n\n\n\n    \n    File\n\n\n    src/app/views/edition-view/edition-outlets/edition-complex/edition-detail/edition-detail.component.ts\n\n\n\n    \n        Description\n    \n    \n        The EditionDetail component.\nIt contains the detail of an edition\nof the edition view of the app.\n\n    \n\n\n\n\n\n    Metadata\n    \n        \n\n\n\n\n\n\n\n\n\n\n\n\n            \n                selector\n                awg-edition-detail\n            \n\n\n\n            \n                styleUrls\n                ./edition-detail.component.scss\n            \n\n\n\n            \n                templateUrl\n                ./edition-detail.component.html\n            \n\n\n\n\n\n\n\n\n        \n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n    \n        import { Component } from '@angular/core';\n\n/**\n * The EditionDetail component.\n *\n * It contains th